template <typename T, typename U>
auto add(T a, U b) {
    return a + b; // Deduced type depends on T+U
}

auto get_lambda() {
    return [](int x) { return x * 2; };
}

struct Box {
    int value = 42;
};

// C++14 onwards (no trailing return needed)
auto get_value(const Box& b) {
    return b.value; // Deduced as int
}

// C++11/14 lambda stored in auto
auto f = [](int x) { return x + 1; };
